  transition: background 0.35s ease, border-color 0.35s ease;
  animation: craft-rise 0.7s ease-out 0.16s both;
}

.craft-tokens__stage-label {
  margin: 0;
  font: 500 0.95rem/1.4 var(--craft-body);
}

.craft-tokens__usage {
  margin: 0 0 1.75rem;
  padding: 1rem 1.15rem 1.15rem;
  border: 1px solid rgba(18, 38, 58, 0.12);
  background: rgba(255, 255, 255, 0.48);
  animation: craft-rise 0.7s ease-out 0.2s both;
}

.craft-tokens__usage-caption {
  margin: 0 0 0.85rem;
  font: 600 0.9rem/1.35 var(--craft-body);
  color: var(--craft-ink);
}

.craft-tokens__usage-caption code {
  font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
  font-size: 0.85em;
  font-weight: 500;
}

.craft-tokens__usage-body {
  display: grid;
  gap: 0.85rem;
}

@media (min-width: 640px) {
  .craft-tokens__usage-body {
    grid-template-columns: 1.35fr 1fr;
    align-items: stretch;
  }
}

.craft-tokens__usage-code {
  margin: 0;
  padding: 0.85rem 0.95rem;
  overflow-x: auto;
  border: 1px solid rgba(18, 38, 58, 0.1);
  background: rgba(18, 38, 58, 0.04);
  font: 500 0.8rem/1.45 ui-monospace, SFMono-Regular, Menlo, monospace;
  color: var(--craft-ink);
  white-space: pre;
}

.craft-tokens__usage-preview {
  display: grid;
  place-items: center;
  min-height: 5.5rem;
  padding: 0.85rem;
  border: 2px solid var(--craft-active);
  color: var(--craft-active);
  background: color-mix(in srgb, var(--craft-active) 14%, white);
  font: 600 0.95rem/1.2 var(--craft-body);
  transition:
    border-color 0.35s ease,
    color 0.35s ease,
    background 0.35s ease;
}

.craft-tokens__stage-label code,
.craft-tokens__swatch code {
  font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
  font-size: 0.85em;
}

.craft-tokens__cta {
  appearance: none;
  border: 0;
  border-radius: 0.2rem;
  padding: 0.7rem 1.1rem;
  font: 600 0.95rem/1.2 var(--craft-body);
  color: #fff;
  background: var(--craft-active);
  cursor: pointer;
  transition: transform 0.2s ease, filter 0.2s ease;
}

.craft-tokens__cta:hover,
.craft-tokens__cta:focus-visible {
  transform: translateY(-1px);
  filter: brightness(1.05);
}

.craft-tokens__cta:focus-visible,
.craft-tokens__swatch:focus-visible {
  outline: 3px solid var(--craft-ink);
  outline-offset: 3px;
}

.craft-tokens__swatches {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  gap: 0.65rem;
  animation: craft-rise 0.7s ease-out 0.24s both;
}

.craft-tokens__swatch {
  width: 100%;
  display: flex;
  align-items: center;
  gap: 0.85rem;
  padding: 0.65rem 0.75rem;
  border: 1px solid rgba(18, 38, 58, 0.14);
  background: rgba(255, 255, 255, 0.55);
  color: inherit;
  text-align: left;
  cursor: pointer;
  transition: border-color 0.2s ease, background 0.2s ease, transform 0.2s ease;
}

.craft-tokens__swatch:hover {
  transform: translateX(2px);
  border-color: rgba(18, 38, 58, 0.28);
}

.craft-tokens__swatch.is-selected {
  border-color: var(--craft-sea);
  background: rgba(255, 255, 255, 0.9);
  box-shadow: inset 3px 0 0 var(--craft-sea);
}

.craft-tokens__chip {
  width: 2rem;
  height: 2rem;
  flex: 0 0 auto;
  border: 1px solid rgba(18, 38, 58, 0.2);
}

.craft-tokens__swatch-text {
  display: grid;
  gap: 0.15rem;
}

.craft-tokens__swatch-label {
  font: 600 0.95rem/1.2 var(--craft-body);
}

@keyframes craft-rise {
  from {
    opacity: 0;
    transform: translateY(10px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@keyframes craft-drift {
  from {
    transform: translate3d(0, 0, 0) scale(1);
  }
  to {
    transform: translate3d(-2%, 3%, 0) scale(1.04);
  }
}

@media (prefers-reduced-motion: reduce) {
  .craft-tokens__atmosphere,
  .craft-tokens h2,
  .craft-tokens__lede,
  .craft-tokens__stage,
  .craft-tokens__usage,
  .craft-tokens__usage-preview,
  .craft-tokens__swatches,
  .craft-tokens__cta,
  .craft-tokens__swatch {
    animation: none !important;
    transition: none !important;
  }
}

@media (max-width: 640px) {
  .craft-tokens {
    padding: 2.5rem 1rem 3rem;
  }

  .craft-tokens h2 {
    font-size: 1.85rem;
  }
}

